import React, { useState, useEffect, useRef } from 'react';
import API from '../api';

const CATEGORIES = [
  { key: 'MOTOR TRIFASICO', icon: '⚡', color: '#00d4ff', label: 'MOTOR TRIFÁSICO' },
  { key: 'BOMBA DE AGUA', icon: '◈', color: '#ffd700', label: 'BOMBA CAPRARI' },
  { key: 'SUCCION', icon: '▽', color: '#00ff88', label: 'SUCCIÓN' },
  { key: 'EXPULSION', icon: '△', color: '#ff8c00', label: 'EXPULSIÓN' },
];

function WaterPumpAnimation({ active }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let frame = 0;
    let animId;
    const W = 340, H = 240;
    canvas.width = W; canvas.height = H;

    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      frame += active ? 0.04 : 0.005;

      // Background glow
      const bg = ctx.createRadialGradient(W / 2, H / 2, 20, W / 2, H / 2, 120);
      bg.addColorStop(0, 'rgba(0,212,255,0.06)');
      bg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, W, H);

      // === SUCTION PIPE (left) ===
      const suctionX = 30, pumpCX = 170, pumpCY = 120;
      ctx.strokeStyle = '#00ff8888';
      ctx.lineWidth = 14;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(suctionX, pumpCY);
      ctx.lineTo(pumpCX - 52, pumpCY);
      ctx.stroke();

      // Flowing water in suction (dashes)
      ctx.strokeStyle = '#00ff88';
      ctx.lineWidth = 4;
      ctx.setLineDash([12, 10]);
      ctx.lineDashOffset = -frame * 60;
      ctx.beginPath();
      ctx.moveTo(suctionX + 4, pumpCY);
      ctx.lineTo(pumpCX - 54, pumpCY);
      ctx.stroke();
      ctx.setLineDash([]);

      // Suction label
      ctx.fillStyle = '#00ff8888';
      ctx.font = '600 9px "Share Tech Mono"';
      ctx.fillText('SUCCIÓN', suctionX - 4, pumpCY - 12);

      // Chupador
      ctx.strokeStyle = '#00ff88';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(suctionX, pumpCY, 10, 0, Math.PI * 2);
      ctx.stroke();
      ctx.fillStyle = 'rgba(0,255,136,0.1)';
      ctx.fill();

      // === PUMP BODY ===
      const gradient = ctx.createRadialGradient(pumpCX, pumpCY, 10, pumpCX, pumpCY, 55);
      gradient.addColorStop(0, 'rgba(0,212,255,0.35)');
      gradient.addColorStop(0.6, 'rgba(0,100,180,0.2)');
      gradient.addColorStop(1, 'rgba(0,50,100,0.1)');
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(pumpCX, pumpCY, 52, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = '#00d4ff';
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.arc(pumpCX, pumpCY, 52, 0, Math.PI * 2);
      ctx.stroke();

      // Inner ring
      ctx.strokeStyle = 'rgba(0,212,255,0.3)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(pumpCX, pumpCY, 38, 0, Math.PI * 2);
      ctx.stroke();

      // === IMPELLER (rotating blades) ===
      ctx.save();
      ctx.translate(pumpCX, pumpCY);
      ctx.rotate(frame * (active ? 3 : 0.3));

      for (let b = 0; b < 6; b++) {
        ctx.rotate(Math.PI / 3);
        ctx.strokeStyle = `rgba(0,212,255,${0.6 + Math.sin(frame * 4 + b) * 0.3})`;
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(6, 0);
        ctx.quadraticCurveTo(16, 6, 30, 3);
        ctx.stroke();
      }

      ctx.restore();

      // Center hub
      const hubG = ctx.createRadialGradient(pumpCX, pumpCY, 0, pumpCX, pumpCY, 8);
      hubG.addColorStop(0, '#00d4ff');
      hubG.addColorStop(1, '#0066aa');
      ctx.fillStyle = hubG;
      ctx.beginPath();
      ctx.arc(pumpCX, pumpCY, 8, 0, Math.PI * 2);
      ctx.fill();

      // Center dot
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.arc(pumpCX, pumpCY, 3, 0, Math.PI * 2);
      ctx.fill();

      // Pump brand label
      ctx.fillStyle = '#00d4ffaa';
      ctx.font = 'bold 8px "Share Tech Mono"';
      ctx.textAlign = 'center';
      ctx.fillText('CAPRARI', pumpCX, pumpCY + 24);
      ctx.textAlign = 'left';

      // === MOTOR (right side) ===
      const motorX = pumpCX + 80, motorY = pumpCY - 36;
      const mW = 75, mH = 72;
      const motorGrad = ctx.createLinearGradient(motorX, motorY, motorX + mW, motorY + mH);
      motorGrad.addColorStop(0, 'rgba(0,180,255,0.2)');
      motorGrad.addColorStop(1, 'rgba(0,80,140,0.1)');
      ctx.fillStyle = motorGrad;
      ctx.strokeStyle = '#00d4ff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.roundRect(motorX, motorY, mW, mH, 6);
      ctx.fill();
      ctx.stroke();

      // Motor shaft connecting to pump
      ctx.strokeStyle = '#00d4ffaa';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(pumpCX + 52, pumpCY);
      ctx.lineTo(motorX, pumpCY);
      ctx.stroke();

      // Motor fins
      for (let f = 0; f < 5; f++) {
        const fy = motorY + 8 + f * 12;
        ctx.strokeStyle = 'rgba(0,212,255,0.3)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(motorX + 4, fy);
        ctx.lineTo(motorX + mW - 4, fy);
        ctx.stroke();
      }

      // Motor label
      ctx.fillStyle = '#00d4ff';
      ctx.font = 'bold 8px "Share Tech Mono"';
      ctx.textAlign = 'center';
      ctx.fillText('MOTOR', motorX + mW / 2, motorY + mH / 2 - 4);
      ctx.fillStyle = '#7ab0cc';
      ctx.font = '7px "Share Tech Mono"';
      ctx.fillText('WEG W22', motorX + mW / 2, motorY + mH / 2 + 8);
      ctx.fillText('2800 RPM', motorX + mW / 2, motorY + mH / 2 + 18);
      ctx.textAlign = 'left';

      // RPM pulse ring
      const pulse = (Math.sin(frame * (active ? 8 : 1)) + 1) / 2;
      ctx.strokeStyle = `rgba(255,215,0,${0.3 + pulse * 0.4})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(motorX + mW / 2, motorY + mH / 2, 20 + pulse * 10, 0, Math.PI * 2);
      ctx.stroke();

      // === DISCHARGE PIPE (top) ===
      const dischargeX = pumpCX, dischargeY = 15;
      ctx.strokeStyle = '#ff8c0088';
      ctx.lineWidth = 14;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(dischargeX, pumpCY - 52);
      ctx.lineTo(dischargeX, dischargeY);
      ctx.stroke();

      ctx.strokeStyle = '#ff8c00';
      ctx.lineWidth = 4;
      ctx.setLineDash([12, 10]);
      ctx.lineDashOffset = frame * 60;
      ctx.beginPath();
      ctx.moveTo(dischargeX, pumpCY - 54);
      ctx.lineTo(dischargeX, dischargeY + 4);
      ctx.stroke();
      ctx.setLineDash([]);

      // Valve symbol
      ctx.strokeStyle = '#ff8c00';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(dischargeX - 10, dischargeY + 18);
      ctx.lineTo(dischargeX + 10, dischargeY + 30);
      ctx.lineTo(dischargeX + 10, dischargeY + 18);
      ctx.lineTo(dischargeX - 10, dischargeY + 30);
      ctx.closePath();
      ctx.stroke();
      ctx.fillStyle = 'rgba(255,140,0,0.1)';
      ctx.fill();

      ctx.fillStyle = '#ff8c00aa';
      ctx.font = '600 9px "Share Tech Mono"';
      ctx.textAlign = 'right';
      ctx.fillText('EXPULSIÓN', dischargeX - 14, dischargeY + 10);
      ctx.textAlign = 'left';

      // Status text
      const statusPulse = (Math.sin(frame * 3) + 1) / 2;
      ctx.fillStyle = active ? `rgba(0,255,136,${0.7 + statusPulse * 0.3})` : `rgba(255,215,0,${0.7 + statusPulse * 0.3})`;
      ctx.font = 'bold 10px "Orbitron"';
      ctx.textAlign = 'center';
      ctx.fillText(active ? '● OPERANDO' : '● EN ESPERA', W / 2, H - 10);
      ctx.textAlign = 'left';

      animId = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(animId);
  }, [active]);

  return <canvas ref={canvasRef} style={{ width: '100%', height: 240, borderRadius: 8 }} />;
}

function CategoryPanel({ cat, items, color, isOpen, onToggle }) {
  return (
    <div style={{ ...cp.card, borderColor: isOpen ? color + '60' : color + '25', boxShadow: isOpen ? `0 0 20px ${color}15` : 'none' }}>
      <div style={{ ...cp.header, background: isOpen ? color + '12' : 'transparent' }}
        onClick={onToggle}>
        <div style={cp.headerLeft}>
          <div style={{ ...cp.dot, background: color, boxShadow: `0 0 8px ${color}` }} />
          <span style={{ ...cp.catTitle, color }}>{cat.label}</span>
          <span style={cp.itemCount}>{items.length} ítems</span>
        </div>
        <div style={{ ...cp.chevron, color, transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)' }}>▼</div>
      </div>

      {isOpen && (
        <div style={cp.body}>
          {/* Spec table */}
          <div style={cp.specGrid}>
            {items.map((item, i) => (
              <div key={item.id} style={{ ...cp.specRow, animationDelay: `${i * 0.04}s` }} className="spec-row">
                <div style={{ ...cp.specName, borderColor: color + '20' }}>
                  <span style={{ color: color + '88', marginRight: 8, fontFamily: 'Orbitron', fontSize: 9 }}>
                    {String(i + 1).padStart(2, '0')}
                  </span>
                  {item.name}
                </div>
                <div style={{ ...cp.specValue, color }}>
                  {item.specification !== item.name ? item.specification : '—'}
                </div>
                <div style={{ ...cp.specStatus, background: item.status === 'good' ? 'rgba(0,255,136,0.1)' : 'rgba(255,211,0,0.1)', color: item.status === 'good' ? '#00ff88' : '#ffd700', borderColor: item.status === 'good' ? 'rgba(0,255,136,0.2)' : 'rgba(255,211,0,0.2)' }}>
                  {item.status === 'good' ? '✓ OK' : '⚠ REV'}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <style>{`
        @keyframes specIn { from{opacity:0;transform:translateX(-8px)} to{opacity:1;transform:translateX(0)} }
        .spec-row { animation: specIn 0.25s ease forwards; opacity: 0; }
      `}</style>
    </div>
  );
}

export default function BombaDeAgua({ equipmentId }) {
  const [components, setComponents] = useState({});
  const [openCat, setOpenCat] = useState('MOTOR TRIFASICO');
  const [isRunning, setIsRunning] = useState(true);
  const [logs, setLogs] = useState([]);
  const [showMaintForm, setShowMaintForm] = useState(false);
  const [maintDesc, setMaintDesc] = useState('');
  const [maintType, setMaintType] = useState('preventivo');
  const [tech, setTech] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!equipmentId) return;
    API.get(`/components/${equipmentId}`).then(r => setComponents(r.data)).catch(() => {});
    API.get(`/equipment/${equipmentId}`).then(r => {
      setLogs(r.data.logs || []);
      setIsRunning(r.data.equipment?.status === 'operational');
    }).catch(() => {});
  }, [equipmentId]);

  const toggleStatus = async () => {
    const newStatus = isRunning ? 'maintenance' : 'operational';
    await API.put(`/equipment/${equipmentId}`, { status: newStatus });
    setIsRunning(!isRunning);
  };

  const submitMaint = async () => {
    if (!maintDesc) return;
    setSaving(true);
    try {
      await API.post('/maintenance', {
        equipment_id: equipmentId,
        type: maintType,
        description: maintDesc,
        technician: tech,
        next_maintenance: new Date(Date.now() + 30 * 86400000).toISOString(),
      });
      const r = await API.get(`/equipment/${equipmentId}`);
      setLogs(r.data.logs || []);
      setShowMaintForm(false);
      setMaintDesc(''); setTech('');
    } catch {}
    setSaving(false);
  };

  return (
    <div style={b.wrap}>
      {/* Header */}
      <div style={b.header}>
        <div style={b.headerLeft}>
          <div style={b.pumpIcon}>
            <span style={{ fontSize: 28 }}>⬡</span>
          </div>
          <div>
            <h2 style={b.title}>BOMBA DE AGUA</h2>
            <p style={b.subtitle}>CAPRARI MEC-A2/80A · S/N 795395/5 · Módena, Italia</p>
          </div>
        </div>
        <div style={b.controls}>
          <button onClick={toggleStatus}
            style={{ ...b.toggleBtn, background: isRunning ? 'rgba(255,51,102,0.15)' : 'rgba(0,255,136,0.15)', borderColor: isRunning ? 'rgba(255,51,102,0.5)' : 'rgba(0,255,136,0.5)', color: isRunning ? '#ff3366' : '#00ff88' }}>
            {isRunning ? '⏹ DETENER' : '▶ OPERAR'}
          </button>
          <button onClick={() => setShowMaintForm(!showMaintForm)} style={b.maintBtn}>
            ⚙ MANTENIMIENTO
          </button>
        </div>
      </div>

      {/* Animated pump + specs side by side */}
      <div style={b.mainRow}>
        {/* Pump animation */}
        <div style={b.pumpCanvas}>
          <div style={b.canvasLabel}>DIAGRAMA DE SISTEMA</div>
          <WaterPumpAnimation active={isRunning} />
          {/* Quick specs */}
          <div style={b.quickSpecs}>
            {[
              { k: 'VOLTAJE', v: '220-380V', c: '#00d4ff' },
              { k: 'RPM', v: '2800', c: '#ffd700' },
              { k: 'Hmax', v: '100 m', c: '#00ff88' },
              { k: 'IP', v: '55', c: '#ff8c00' },
            ].map(qs => (
              <div key={qs.k} style={b.qSpec}>
                <div style={{ ...b.qSpecVal, color: qs.c }}>{qs.v}</div>
                <div style={b.qSpecKey}>{qs.k}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Components */}
        <div style={b.compCol}>
          <div style={b.compTitle}>COMPONENTES DEL SISTEMA</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {CATEGORIES.map(cat => (
              <CategoryPanel
                key={cat.key}
                cat={cat}
                color={cat.color}
                items={components[cat.key] || []}
                isOpen={openCat === cat.key}
                onToggle={() => setOpenCat(openCat === cat.key ? null : cat.key)}
              />
            ))}
          </div>
        </div>
      </div>

      {/* Maintenance form */}
      {showMaintForm && (
        <div style={b.maintForm}>
          <div style={b.maintFormTitle}>⚙ REGISTRAR MANTENIMIENTO</div>
          <div style={b.maintRow}>
            <div style={b.maintField}>
              <label style={b.maintLabel}>TIPO</label>
              <select style={b.maintInput} value={maintType} onChange={e => setMaintType(e.target.value)}>
                <option value="preventivo">Preventivo</option>
                <option value="correctivo">Correctivo</option>
                <option value="predictivo">Predictivo</option>
              </select>
            </div>
            <div style={b.maintField}>
              <label style={b.maintLabel}>TÉCNICO</label>
              <input style={b.maintInput} value={tech} onChange={e => setTech(e.target.value)} placeholder="Nombre del técnico" />
            </div>
          </div>
          <div style={b.maintField}>
            <label style={b.maintLabel}>DESCRIPCIÓN</label>
            <textarea style={{ ...b.maintInput, minHeight: 70, resize: 'vertical' }}
              value={maintDesc} onChange={e => setMaintDesc(e.target.value)}
              placeholder="Describa el trabajo realizado..." />
          </div>
          <button onClick={submitMaint} disabled={saving} style={b.submitBtn}>
            {saving ? 'REGISTRANDO...' : '✓ GUARDAR REGISTRO'}
          </button>
        </div>
      )}

      {/* Maintenance logs */}
      {logs.length > 0 && (
        <div style={b.logsSection}>
          <div style={b.logsTitle}>📋 HISTORIAL DE MANTENIMIENTO</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {logs.map(log => (
              <div key={log.id} style={b.logRow}>
                <div style={{ ...b.logType, color: log.type === 'preventivo' ? '#00d4ff' : '#ffd700' }}>
                  {log.type?.toUpperCase()}
                </div>
                <div style={b.logDesc}>{log.description}</div>
                <div style={b.logMeta}>
                  <span style={b.logTech}>{log.technician || '—'}</span>
                  <span style={b.logDate}>{new Date(log.date).toLocaleDateString('es-BO')}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <style>{`
        input:focus,select:focus,textarea:focus { outline:none; border-color:#00d4ff !important; }
      `}</style>
    </div>
  );
}

